// Lỗi DỰ KIẾN: trả như giá trị (Result). Lỗi KHÔNG dự kiến: throw -> error.js
function parseAge(input) {
  const n = Number(input);
  if (!Number.isInteger(n) || n < 0 || n > 130) return { ok: false, error: "Tuổi không hợp lệ" };
  return { ok: true, value: n };
}
console.log(JSON.stringify(parseAge("20")));
console.log(JSON.stringify(parseAge("abc")));

// Mô phỏng retry() của error.js: thử lại một thao tác có thể thất bại
async function withRetry(fn, attempts) {
  let last;
  for (let i = 0; i < attempts; i++) {
    try { return await fn(i); } catch (e) { last = e; }
  }
  throw last;
}
withRetry(async (i) => { if (i < 2) throw new Error("lỗi " + i); return "ok sau " + (i + 1) + " lần"; }, 3).then(console.log);

